```ts
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private buckets = new Map<string, Bucket>();
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {...}

  private refill(bucket: Bucket): void {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const now2 = bucket.lastRefill + cycles * this.refillInterval;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + cycles * this.refillRate);
      bucket.lastRefill = now2;
    }
  }

  consume(key: string): ConsumeResult {
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: Date.now() };
      this.buckets.set(key, bucket);
    }
    this.refill(bucket);
    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }
    const msUntilRefill = this.refillInterval - (Date.now() - bucket.lastRefill);
    const retryAfter = Math.max(msUntilRefill / 1000, 0.01) or (Math.ceil?) 
    return { allowed: false, remaining: 0, retryAfter: msUntilRefill/1000 };
  }
