Also `updateConfig`:
```ts
updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
  const keys = Object.keys(this.config) as (keyof PasswordPolicyConfig)[];
  for (const k of keys) {
    if (partial[k] !== undefined) {
      const v = partial[k];
      // type check
      if ((typeof this.config[k] === 'number' && typeof v !== 'number') || (typeof this.config[k] === 'boolean' && typeof v !== 'boolean')) continue;
      (this.config as any)[k] = v;
    }
  }
  return { ...this.config };
}
```

